Thought: I need to find the smallest positive integer $a$ such that $x^4 + a^2$ is not prime for any integer $x$. Let me systematically check small values of $a$ by testing if $x^4 + a^2$ is ever prime for various values of $x$.

<code>
def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def check_a(a, max_x=100):
    """Check if x^4 + a^2 is never prime for x from -max_x to max_x"""
    for x in range(-max_x, max_x + 1):
        val = x**4 + a**2
        if is_prime(val):
            return False, x, val
    return True, None, None

# Check small values of a
for a in range(1, 20):
    result, x_val, val = check_a(a, max_x=50)
    print(f"a={a}: {'Always composite' if result else f'Prime at x={x_val}, value={val}'}")
</code>

